    s = "( ( { < { < { < > } > } > ) ( ) ( { [ ( < ( < < { ( { < > } ) } > > ) > ) { ( { < ( { [ ] } ( ) ) > } < { < { { ( ) } } > { < [ { ( ) } ] > } } > ) } [ [ ( ) ] ]"

    stack = []  # Stack to keep track of opening brackets

    for char in s:
        if char == '(':
            stack.append('(')
        elif char == ')':
            if not stack or stack[-1] != '(':
                print(f"Error at {char}: expected '(' but found '{stack[-1]}' on top of stack")
                return False
            else:
                stack.pop()
        elif char == '[':
            stack.append('[')
        elif char == ']':
            if not stack or stack[-1] != '[':
                print(f"Error at {char}: expected '[' but found '{stack[-1]}' on top of stack")
                return False
            else:
                stack.pop()
        elif char == '{':
            stack.append('{')
        elif char == '}':
            if not stack or stack[-1] != '{':
                print(f"Error at {char}: expected '{{' but found '{stack[-1]}' on top of stack")
                return False
            else:
                stack.pop()
        elif char == '<':
            stack.append('<')
        elif char == '>':
            if not stack or stack[-1] != '<':
                print(f"Error at {char}: expected '<' but found '{stack[-1]}' on top of stack")
                return False
            else:
                stack.pop()

    # Remaining unclosed brackets in the order they were opened (first to last)
    remaining = list(stack)
    print(f"Unclosed opening brackets: {remaining}")

    # To close them properly, we need closing brackets for each from top of stack down? 
    # No, if '(' was first and '<' is later on the stack, then '>' must come before '>'.
    # The last opened bracket needs to be closed first. So reverse the remaining list.

    result = []
    for i in range(len(remaining) - 1, -1, -1):
        open_bracket = remaining[i]
        if open_bracket == '(':
            result.append(')')
        elif open_bracket == '[':
            result.append(']')
        elif open_bracket == '{':
            result.append('}')
        elif open_bracket == '<':
            result.append('>')

    print(f"Closing brackets needed (separated by space): {' '.join(result)}")

